      "data": {
        "calendar": {
          "items": []
        }
      },
      "state": {
        "loading": true
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "schedule_glyph",
      "src": "resources/base/media/icon_schedule.png",
      "use": "calendar glyph",
      "description": "日程图标，可用于表达从日历拉取持仓提醒或查看相关日程。",
      "bindTo": "/asset/glyph",
      "static": true
    }
  ]
}

